mapper.select:
SELECT DISTINCT cp.project_id, cp.project_name, cp.team_name, cp.status, cp.completion_rate, cp.deadline, cp.created_at, leader.real_name AS leader_name, cn.title AS notice_title FROM competition_project cp JOIN sys_user leader ON leader.user_id = cp.leader_id AND leader.is_deleted = 0 JOIN competition_notice cn ON cn.notice_id = cp.notice_id AND cn.is_deleted = 0 WHERE cp.is_deleted = 0
AND (cp.project_name LIKE CONCAT('%', #{keyword}, '%') OR leader.real_name LIKE CONCAT('%', #{keyword}, '%') OR cn.title LIKE CONCAT('%', #{keyword}, '%'))
AND cp.status = #{status}
AND cp.notice_id = #{noticeId}
ORDER BY cp.created_at DESC
